import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = 1;
        final long MOD_CONST = 1000000007;

        for (int t = 0; t < T; t++) {
            int total_nodes = scanner.nextInt();
            int factor_value = scanner.nextInt();

            int[] k_sequence = new int[total_nodes];
            for (int i = 0; i < total_nodes; i++) {
                k_sequence[i] = (factor_value * i) % total_nodes;
            }

            if (factor_value == 0) {
                System.out.println(powMod(total_nodes, total_nodes - 1, MOD_CONST));
                continue;
            }
            if (factor_value == 1) {
                System.out.println(powMod(total_nodes, total_nodes, MOD_CONST));
                continue;
            }

            int[] visited_flags = new int[total_nodes];
            int[] cycle_sizes_count = new int[total_nodes + 1]; // size index up to total_nodes
            long result = 1;

            for (int start_point = 0; start_point < total_nodes; start_point++) {
                if (visited_flags[start_point] != 0) {
                    continue;
                }
                int length_of_cycle = 1;
                int current_point = start_point;
                visited_flags[current_point] = 1;
                while (visited_flags[k_sequence[current_point]] == 0) {
                    current_point = k_sequence[current_point];
                    visited_flags[current_point] = 1;
                    length_of_cycle++;
                }
                cycle_sizes_count[length_of_cycle]++;
            }

            for (int size = 2; size < total_nodes; size++) {
                if (cycle_sizes_count[size] != 0) {
                    long total_size = size * cycle_sizes_count[size] + 1;
                    result = (result * powMod(total_size, cycle_sizes_count[size], MOD_CONST)) % MOD_CONST;
                }
            }

            System.out.println(result);
        }
        scanner.close();
    }

    private static long powMod(long base, long exp, long mod) {
        long result = 1;
        long current_power = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * current_power) % mod;
            }
            current_power = (current_power * current_power) % mod;
            exp >>= 1;
        }
        return result;
    }
}
